import{_ as t,o as e,c as s,a5 as d}from"./chunks/framework.CslsFoWx.js";const h=JSON.parse('{"title":"Matériel","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/11-hardware.md","filePath":"generated/modules/11-hardware.md","lastUpdated":null}'),n={name:"modules/11-hardware.md"};function r(i,a,o,p,l,c){return e(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="materiel" tabindex="-1">Matériel <a class="header-anchor" href="#materiel" aria-label="Permalink to &quot;Matériel&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 1 · <a href="/VendoraSystem-docs/specs/11-hardware">spécification complète</a></span></p><p>Imprimantes ESC/POS (format logique 58 / 80 mm, file durable, états DLE EOT, imprimante simulée), bons cuisine par poste, tiroir-caisse sous PIN, douchettes HID, scan caméra natif et planches d&#39;étiquettes A4. Le code est livré et prouvé sur émulateur / simulateur avec de fausses imprimantes TCP et l&#39;imprimante simulée (phase 1, lots 2.4, 2.17, 2.22, 2.26) ; le lot R5 ajoute Bluetooth / USB, la recherche réseau, l&#39;identité légale du ticket, les étiquettes de balance et l&#39;écran de file d&#39;impression ; la validation sur matériel physique reste à faire par l&#39;utilisateur, et la configuration des imprimantes au niveau du magasin, l&#39;étiqueteuse, la balance connectée et l&#39;afficheur sont à venir.</p><div class="kpis"><div><b>15</b><span>faites</span></div><div><b>5</b><span>partielles</span></div><div><b>6</b><span>à faire</span></div><div><b>2</b><span>bloquées</span></div></div><h2 id="impression-des-tickets" tabindex="-1">Impression des tickets <a class="header-anchor" href="#impression-des-tickets" aria-label="Permalink to &quot;Impression des tickets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Format logique et rendu ESC/POS 58 / 80 mm</strong><br><span class="muted">Les tickets sont décrits dans un format logique indépendant de l&#39;imprimante et rendus en ESC/POS selon la largeur (32 ou 48 colonnes) au moment d&#39;imprimer.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-03</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-ios">📷</a></td></tr><tr><td><strong>Imprimante réseau TCP 9100</strong><br><span class="muted">La caisse imprime en TCP sur port 9100 (IP, port, largeur dans les Réglages imprimante), sans internet.<br><i>Prouvé avec une fausse imprimante <code>nc</code> (ticket réel de 512 o) ; imprimante thermique réelle à valider (VALIDATION-MATERIEL §3).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-02, RG-HW-14</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-ios">📷</a></td></tr><tr><td><strong>Imprimantes Bluetooth et USB</strong><br><span class="muted">Connexion d&#39;une imprimante Bluetooth (SPP / MFi) ou USB (Android) derrière le même registre de pilotes.<br><i>Fait (lot R5) : adresses <code>bt:</code> / <code>usb:</code> / <code>ble:</code> routées par <code>PrinterDriverRegistry</code> ; Android Bluetooth SPP (imprimantes appairées, autorisation BLUETOOTH_CONNECT) et USB hôte (sortie bulk, autorisation par imprimante) ; iOS Bluetooth basse énergie (CoreBluetooth — MFi non retenu, certification Apple). Liaison absente de l&#39;appareil : job gardé en file. Reste : validation sur imprimantes physiques (VALIDATION-MATERIEL).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-02</td><td>2.17, R5</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r5-materiel">📷</a></td></tr><tr><td><strong>Contenu du ticket de vente</strong><br><span class="muted">Nom ou logo du magasin, numéro, vendeur, lignes, remises, TVA par taux, paiements et rendu, n° fiscal + empreinte, DUPLICATA à la réimpression.<br><i>Identité légale saisie par l&#39;owner (« Ticket et balance » : raison sociale, adresse, téléphone, matricule fiscal, RNE, message de pied) imprimée sur tous les tickets (lot R5) ; QR du reçu digital (lot 3.5). Accents translittérés en ASCII (pas de code page).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-HW-15</td><td>1.x, 2.22, R5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-migrations">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r5-materiel">📷</a></td></tr><tr><td><strong>Logo bitmap sur le ticket</strong><br><span class="muted">Le logo du magasin (variante monochrome tramée ≤ 384 points) est imprimé en <code>GS v 0</code> en tête du ticket de vente et d&#39;annulation, repli sur le nom en double taille.<br><i>Logo aussi imprimé sur les rapports X / Z et les bons cuisine (lot R5), prouvé sur la vraie stack avec une imprimante réseau factice.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-HW-03, RG-HW-15</td><td>2.22, 2.25, R5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-logo-config-appareil">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r5-materiel">📷</a></td></tr><tr><td><strong>Zone fiscale par pays</strong><br><span class="muted">Le ticket porte la zone fiscale du pays : n° fiscal et empreinte chaînée en France ; QR fiscal NACEF obligatoire en Tunisie.<br><i>Zone FR faite (socle fiscal 1/2) ; QR fiscal NACEF bloqué par le cahier des charges (géo-bloqué, action terrain).</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td>RG-HW-16</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-ios">📷</a></td></tr><tr><td><strong>Rapport Z imprimé et DUPLICATA</strong><br><span class="muted">Le Z s&#39;imprime automatiquement à la clôture (original unique), puis en DUPLICATA sous PIN manager, réimpression tracée.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-15</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-rapport-z-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-android">📷</a></td></tr></tbody></table><h2 id="file-d-impression-etats" tabindex="-1">File d&#39;impression &amp; états <a class="header-anchor" href="#file-d-impression-etats" aria-label="Permalink to &quot;File d&#39;impression &amp; états&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>File d&#39;impression durable, jamais bloquante</strong><br><span class="muted">Toute impression passe par une file persistante avec tentatives bornées, dans l&#39;ordre d&#39;enfilement ; un échec d&#39;impression ne bloque jamais la vente.<br><i>Débranchement réel d&#39;une imprimante pendant un ticket à valider (VALIDATION-MATERIEL §3).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-04, RG-HW-05</td><td>1.x, 2.4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a></td></tr><tr><td><strong>États d&#39;imprimante et suspension de la file</strong><br><span class="muted">La file interroge chaque imprimante visée en DLE EOT avant d&#39;envoyer : plus de papier ou capot ouvert suspendent la file sans tentative consommée, papier bas prévient, bandeau en caisse.<br><i>Prouvé sur émulateur avec l&#39;imprimante simulée et une fausse imprimante TCP qui répond au statut ; capot / papier réels à valider (VALIDATION-MATERIEL §3).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-06</td><td>2.17</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-imprimante-simulee">📷</a></td></tr><tr><td><strong>Imprimante simulée</strong><br><span class="muted">Adresse réservée <code>simulateur</code> : tickets gardés en mémoire, état pilotable depuis les réglages des deux apps, texte du dernier ticket affiché.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-06</td><td>2.17</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-imprimante-simulee">📷</a></td></tr><tr><td><strong>Écran de la file d&#39;impression</strong><br><span class="muted">La caisse liste les travaux d&#39;impression avec actions Réimprimer, Rediriger vers une autre imprimante et Abandonner (abandon tracé).<br><i>Lot R5 : nature et libellé de chaque job (bon cuisine, ticket, rapport, page de test), filtres, Réimprimer, Rediriger vers l&#39;imprimante de caisse ou d&#39;un autre poste, Abandonner avec motif (audit <code>PRINT_JOB / ABANDONED</code>) — Android et iOS. Les jobs d&#39;avant la mise à jour restent typés « Ticket de caisse ».</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-04</td><td>2.4, R5</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r5-materiel">📷</a></td></tr></tbody></table><h2 id="bons-cuisine" tabindex="-1">Bons cuisine <a class="header-anchor" href="#bons-cuisine" aria-label="Permalink to &quot;Bons cuisine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Bons cuisine routés par poste</strong><br><span class="muted">Un bon par poste à chaque envoi, gros caractères, table, serveur, heure, modificateurs « + », note « ! », sans prix ; imprimeur unique désigné au back-office.<br><i>Prouvé avec deux fausses imprimantes TCP (80 et 58 mm) ; sur 58 mm en double taille un nom long se replie sur deux lignes.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-HW-07, RG-REST-11</td><td>2.4, 2.26</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-bons-cuisine">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a></td></tr><tr><td><strong>Alerte imprimante cuisine injoignable</strong><br><span class="muted"><code>KitchenTicketPrintFailed</code> (au plus une alerte par imprimante et par 10 min), toast / alerte sur l&#39;appareil émetteur et alerte « Imprimante cuisine » au back-office.<br><i>Lot R5 : bandeau sur l&#39;écran cuisine du poste concerné (CA-05), levé par <code>KitchenTicketPrintRecovered</code> quand la file de la caisse est vidée (sinon après 15 min) ; redirection depuis la file d&#39;impression. Les postes sont regroupés par adresse d&#39;imprimante.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-HW-07</td><td>2.17, 2.26, R5</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-restaurant">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-r5-materiel">📷</a></td></tr></tbody></table><h2 id="tiroir-caisse" tabindex="-1">Tiroir-caisse <a class="header-anchor" href="#tiroir-caisse" aria-label="Permalink to &quot;Tiroir-caisse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Ouverture du tiroir sous PIN manager</strong><br><span class="muted">Impulsion ESC p envoyée en direct (jamais mise en file), hors vente sous PIN manager + motif, tracée <code>CashDrawerOpened</code> et dans le journal d&#39;audit.<br><i>Octets <code>1B 70 00 19 FA</code> reçus par une fausse imprimante ; tiroir RJ11 réel à valider (VALIDATION-MATERIEL §4).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-HW-08, RG-CASH-17</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-pin-manager-ios">📷</a></td></tr><tr><td><strong>Tiroir interdit aux téléphones de salle et kiosques</strong><br><span class="muted">Seules les caisses peuvent commander le tiroir ; le téléphone de salle encaisse sans tiroir.<br><i>Fait pour le téléphone de salle (session sans tiroir) ; le cas KIOSK (CA-07) attend l&#39;app kiosque de la phase 4.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-08</td><td>2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr></tbody></table><h2 id="douchettes" tabindex="-1">Douchettes <a class="header-anchor" href="#douchettes" aria-label="Permalink to &quot;Douchettes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Douchette HID avec capture globale</strong><br><span class="muted">Détecteur de rafale : un scan douchette est pris sans focus, y compris quand la recherche a le focus, et suspend la recherche pendant la rafale.<br><i>Scan perdu sur Android quand une boîte de dialogue est ouverte (comportement à décider, TODO-PHASE1 §2) ; prouvé par <code>adb input</code> / saisie simulée, douchettes Bluetooth et USB réelles à valider (VALIDATION-MATERIEL §1).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-09</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-scan-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-scan-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-mesure-100ms-android">📷</a></td></tr></tbody></table><h2 id="scan-camera" tabindex="-1">Scan caméra <a class="header-anchor" href="#scan-camera" aria-label="Permalink to &quot;Scan caméra&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Scan caméra natif</strong><br><span class="muted">CameraX + ML Kit sur Android, VisionKit sur iOS (repli saisie manuelle au simulateur) : EAN-13/8, UPC-A/E, QR, Code 128, viseur, torche, anti-doublon 1,5 s, bip + vibration.<br><i>Objectif &lt; 500 ms à mesurer sur appareil physique (VALIDATION-MATERIEL §2).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-10</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-scan-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-scan-ios">📷</a></td></tr></tbody></table><h2 id="etiquettes" tabindex="-1">Étiquettes <a class="header-anchor" href="#etiquettes" aria-label="Permalink to &quot;Étiquettes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Planches d&#39;étiquettes A4</strong><br><span class="muted">Le back-office génère des codes internes EAN-13 serveur-autoritaires et un PDF A4 (gabarits 24 / 40 / 65, case de départ sur planche entamée), codes relus par ZXing.<br><i>Sélection par catégorie / réception et filtre « prix modifié depuis le … » non faits ; EAN-8 et codes libres non imprimables ; impression physique de la planche non testée.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-HW-11</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-etiquettes-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-etiquettes-ios">📷</a></td></tr></tbody></table><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Écran « Diagnostic matériel »</strong><br><span class="muted">Dans les deux apps : verdict de vitesse de la douchette, objectif caméra, imprimante, tiroir, bip, réseau, rapport copiable.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-09, RG-HW-10</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-diagnostic-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-diagnostic-ios">📷</a></td></tr><tr><td><strong>Validation sur matériel physique</strong><br><span class="muted">Douchettes Bluetooth / USB, caméra &lt; 500 ms, imprimante thermique 80 / 58 mm, tiroir RJ11, Wi-Fi coupé, planche A4 réelle scannée en caisse.<br><i>À exécuter par l&#39;utilisateur sur son matériel (VALIDATION-MATERIEL §1 à §6, TODO-PHASE1 §1) ; un iPhone / iPad physique demande la signature d&#39;équipe.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td>RG-HW-02, RG-HW-06, RG-HW-08, RG-HW-09, RG-HW-10, RG-HW-11</td><td>1.x</td><td></td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Imprimantes du magasin et attribution par rôle</strong><br><span class="muted">Entité <code>Printer</code> au niveau du magasin (rôles RECEIPT, KITCHEN, REPORT, KIOSK), attributions par appareil, API <code>/printers</code> et <code>/printer-assignments</code>.<br><i>Non planifié au TRACKING : l&#39;imprimante est un réglage local de chaque appareil (IP, port, largeur) et les postes portent l&#39;adresse de leur imprimante.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-HW-01, RG-HW-14</td><td></td><td></td></tr><tr><td><strong>Découverte des imprimantes</strong><br><span class="muted">Recherche réseau (port 9100, Bonjour / mDNS) et appairage Bluetooth / USB pour installer une caisse en deux gestes.<br><i>Lot R5 : recherche du port 9100 sur le /24 de l&#39;appareil (64 en parallèle, 800 ms, sonde d&#39;état) — Android et iOS ; imprimantes Bluetooth appairées / USB branchées (Android), BLE à portée (iOS). Reste : Bonjour / mDNS.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-02</td><td>R5</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r5-materiel">📷</a></td></tr><tr><td><strong>Modèles de tickets configurables</strong><br><span class="muted"><code>ReceiptTemplate</code> par magasin : en-tête, pied, mentions légales, édités au back-office et diffusés par <code>ReceiptTemplateUpdated</code>.<br><i>Non planifié au TRACKING ; le logo et le nom de marque viennent du thème (lots 2.22 / 2.25).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-HW-15</td><td></td><td></td></tr></tbody></table><h2 id="phases-ulterieures" tabindex="-1">Phases ultérieures <a class="header-anchor" href="#phases-ulterieures" aria-label="Permalink to &quot;Phases ultérieures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Ticket kiosque</strong><br><span class="muted">Numéro de commande en très grands caractères, récapitulatif court, QR de suivi.<br><i>Phase 4 (spec 09).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-HW-01</td><td></td><td></td></tr><tr><td><strong>Code-barres à poids embarqué</strong><br><span class="muted">La caisse décode les EAN-13 de balance (préfixe 2x : code produit + poids ou prix).<br><i>Lot R5 (<code>ScaleBarcode</code>) : EAN-13 préfixe 2x, poids en grammes ou prix encodé, préfixes réglés par l&#39;owner (« Ticket et balance »), ligne pesée par étiquette — Android et iOS.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-HW-12</td><td>R5</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-r5-materiel">📷</a></td></tr><tr><td><strong>Balance connectée et afficheur client</strong><br><span class="muted">Liaison série / USB avec la balance (Dialog06, Toledo, CAS) et afficheur client 2×20 ou second écran.<br><i>Phase ultérieure (v2).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-HW-12</td><td></td><td></td></tr><tr><td><strong>Étiqueteuses dédiées</strong><br><span class="muted">Étiquettes unitaires sur Zebra (ZPL) ou Brother via un agent d&#39;impression local.<br><i>Phase ultérieure (reste de la section Étiquettes).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-HW-11</td><td>1.x</td><td></td></tr><tr><td><strong>Agent d&#39;impression local pour le web</strong><br><span class="muted">Petit service HTTP local qui imprime pour le back-office au format logique.<br><i>Différé par la spec : le back-office produit des PDF (Z, clôtures, étiquettes).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-HW-13</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Validation sur matériel physique : douchettes BT / USB, caméra, imprimante thermique réelle (débranchement, papier, capot), tiroir RJ11, Wi-Fi coupé, planche A4 imprimée (VALIDATION-MATERIEL §1 à §6).</li><li>Transports Bluetooth et USB derrière le registre de pilotes.</li><li>Imprimantes déclarées au niveau du magasin, attribution par rôle, découverte réseau et modèles de tickets configurables.</li><li>Écran de file d&#39;impression : distinguer les bons cuisine, rediriger, abandonner (tracé).</li><li>Alerte d&#39;imprimante cuisine sur le KDS du poste ; code page ESC/POS (le « · » devient « ? »).</li><li>QR du reçu digital et mentions légales sur le ticket ; logo sur les tickets Z / X / cuisine.</li><li>QR fiscal NACEF (bloqué par le cahier des charges).</li><li>Scan pendant une boîte de dialogue ouverte sur Android : comportement à décider.</li><li>Étiquettes : sélection par catégorie, filtre « prix modifié depuis », EAN-8, écran du préfixe interne.</li><li>Code poids embarqué, balance connectée, afficheur client, étiqueteuses dédiées, agent d&#39;impression web, ticket kiosque (phases ultérieures).</li></ul>',26)])])}const b=t(n,[["render",r]]);export{h as __pageData,b as default};
